def ev(expr):
    st = []
    for t in expr.split():
        if t in '+-*/':
            r = st.pop(); l = st.pop()   # first pop is the RIGHT operand
            st.append({'+': l + r, '-': l - r, '*': l * r, '/': l / r}[t])
        else:
            st.append(int(t))
    return st
