import random
def ins(a):
    a = a[:]; c = 0
    for j in range(1, len(a)):
        k = a[j]; i = j - 1
        while i >= 0:
            c += 1
            if a[i] > k: a[i + 1] = a[i]; i -= 1
            else: break
        a[i + 1] = k
    return c
def sel(a, key=lambda v: v):
    a = a[:]; c = 0
    for i in range(len(a) - 1):
        m = i
        for j in range(i + 1, len(a)):
            c += 1
            if key(a[j]) < key(a[m]): m = j
        a[i], a[m] = a[m], a[i]
    return a, c
def bub(a):
    a = a[:]; s = 0
    for i in range(len(a) - 1):
        for j in range(len(a) - 1 - i):
            if a[j] > a[j + 1]: a[j], a[j + 1] = a[j + 1], a[j]; s += 1
    return s
inv = lambda a: sum(a[i] > a[j] for i in range(len(a)) for j in range(i + 1, len(a)))
